import os

def get_storage_client():
    return storage.Client(project=os.getenv('GOOGLE_CLOUD_PROJECT'))

def get_bucket(client, bucket_name):
    return client.bucket(bucket_name)

def get_blob(bucket, object_name):
    return bucket.blob(object_name)

class StorageObject:
    def __init__(self, name, data, content_type='application/octet-stream'):
        self.name = name
        self.data = data
        self.content_type = content_type

class PresignedUrl:
    def __init__(self, url):
        self.url = url

class ObjectMetadata:
    def __init__(self, metadata):
        self.metadata = metadata

import boto3
import io

def ocr_document(bucket_name, object_name):
    client = boto3.client('textract')
    response = client.detect_document_text(
        Document={'S3Object':{'Bucket': bucket_name, 'Name': object_name}}
    )
    text = ''.join([item['Text'] for item in response['Blocks'] if item['BlockType'] == 'LINE'])
    return text

